async function open(page,action='openStadium',args=[]){
 const errors=[];page.on('pageerror',e=>errors.push(e.message));await page.clock.install();await page.clock.pauseAt(new Date(Date.now()+1000));
 const source=original.slice(0,original.lastIndexOf('(async()=>{try{app.innerHTML=')).replace(/^import .*;\s*$/gm,'')+setup;
 await page.route('**/app.js',route=>route.fulfill({contentType:'text/javascript',body:source}));await page.goto('/');await page.waitForFunction(action=>typeof window[action]==='function',action);await page.evaluate(({action,args})=>window[action](...args),{action,args});await expect(page.locator('#be-replay-next')).toBeEnabled({timeout:30000});return errors;
}
async function frame(page){await page.locator('#be-replay-next').click();await page.clock.runFor(10);for(let n=0;n<1000&&await page.locator('.be-stadium').getAttribute('data-flight');n++)await page.clock.runFor(20);if(await page.locator('#be-replay-auto').isEnabled())await page.locator('#be-replay-auto').click();}
for(const width of [320,390,1080])test('compact replay, transparent zone, records and two actions '+width,async({page})=>{
 await page.setViewportSize({width,height:900});const errors=await open(page);await expect(page.locator('.be-replay-controls>button')).toHaveCount(2);await expect(page.locator('#be-replay-all,#be-replay-mode,.be-broadcast-inning-nav,.be-broadcast-zone,.be-broadcast-lineups,.be-zone-marker')).toHaveCount(0);await expect(page.locator('#be-replay-speed option')).toHaveText(['1배','2배','3배']);
 const color=await page.locator('.be-broadcast-zone-grid>span').first().evaluate(el=>getComputedStyle(el).backgroundColor);expect(color).toMatch(/^rgba\(/);
 await frame(page);await expect(page.locator('#be-pitch-records li')).toHaveCount(1);await expect(page.locator('#be-pitch-records')).toContainText('볼');await expect(page.locator('#be-duel-seen')).toHaveText('1');await expect(page.locator('#be-catcher-lead')).toContainText('리드 · 재현');await expect(page.locator('.be-pitch-players,.be-batter-stance,#be-batter-swing')).toHaveCount(0);await page.locator('.be-stadium').screenshot({path:'test-results/compact-pitch-'+width+'.png'});
 const centered=await page.evaluate(()=>{const r=document.querySelector('.be-stadium').getBoundingClientRect(),h=document.querySelector('#be-stadium-velocity').getBoundingClientRect();return Math.abs((r.left+r.width/2)-(h.left+h.width/2))});expect(centered).toBeLessThan(2);
 await expect(page.locator('.be-flight-trail,.be-throw-trail,.be-ball-flight,#be-stadium-pitches>path')).toHaveCount(0);await expect(page.locator('#be-pitch-trail path')).toHaveCount(1);
 await frame(page);await expect(page.locator('#be-pitch-records li')).toHaveCount(2);await expect(page.locator('#be-stadium-pitches circle')).toHaveCount(2);await frame(page);await expect(page.locator('#be-stadium-result')).toHaveText('타격');await frame(page);await expect(page.locator('.be-stadium')).toHaveAttribute('data-view','field');await expect(page.locator('.be-pitch-record-panel')).toBeHidden();await expect(page.locator('.be-stadium-hud')).toBeHidden();await expect(page.locator('#be-stadium-runners')).toContainText('타자1');await expect(page.locator('[data-fielder="SS"]')).toContainText('홈 유격수');
 await page.locator('.be-stadium').screenshot({path:'test-results/clean-field-'+width+'.png'});expect(await page.evaluate(()=>window.currentSnapshot()===window.fixtureBefore)).toBe(true);expect(errors).toEqual([]);expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1)).toBe(true);await page.evaluate(()=>beCloseGameReplay());
});
test('stop freezes motion, resume and resize finish on the exact numbered marker',async({page})=>{
 const errors=await open(page);await page.locator('#be-replay-next').click();await page.clock.runFor(240);await page.evaluate(()=>window.lastBall=document.querySelector('.be-flying-ball'));await page.locator('#be-replay-auto').click();const stopped=await page.locator('.be-flying-ball').getAttribute('transform');await page.clock.runFor(2000);await expect(page.locator('.be-flying-ball')).toHaveAttribute('transform',stopped);
 await page.setViewportSize({width:450,height:900});await page.clock.runFor(32);await page.locator('#be-replay-next').click();await page.clock.runFor(1800);await expect(page.locator('.be-flying-ball')).toHaveCount(0);
 const difference=await page.evaluate(()=>{const m=window.lastBall.transform.baseVal.consolidate().matrix,c=document.querySelector('.be-pitch-new circle');return Math.hypot(m.e-Number(c.getAttribute('cx')),m.f-Number(c.getAttribute('cy')))});expect(difference).toBeLessThan(.08);await page.locator('#be-replay-auto').click();expect(errors).toEqual([]);await page.evaluate(()=>beCloseGameReplay());
});
test('speed modes change cadence without skipping pitches and highlights keep full score and pitch count',async({page})=>{
 const errors=await open(page);await page.locator('#be-replay-highlights').check();await page.locator('#be-replay-speed').selectOption('3');await page.locator('#be-replay-next').click();await page.clock.runFor(250);await page.locator('#be-replay-auto').click();await expect(page.locator('#be-duel-seen')).toHaveText('3');await expect(page.locator('#be-pitch-records li')).toHaveCount(3);await expect(page.locator('#be-stadium-result')).toHaveText('타격');await expect(page.locator('#be-duel-total')).toHaveText('3');
 await page.locator('#be-replay-next').click();await page.clock.runFor(30000);await expect(page.locator('#be-replay-current-score')).toHaveText('0 : 1');await expect(page.locator('#be-replay-next')).toBeDisabled();await expect(page.locator('#be-replay-auto')).toBeDisabled();expect(await page.evaluate(()=>window.currentSnapshot()===window.fixtureBefore)).toBe(true);expect(errors).toEqual([]);await page.evaluate(()=>beCloseGameReplay());
});
for(const action of ['steal','pickoff','rundown'])for(const out of [false,true])test('clean running replay '+action+' '+out,async({page})=>{
 const errors=await open(page,'openRunning',[action,out]);await frame(page);await expect(page.locator('.be-stadium')).toHaveAttribute('data-view','field');await expect(page.locator('.be-stadium-hud')).toBeHidden();await expect(page.locator('.be-pitch-record-panel')).toBeHidden();await expect(page.locator('[data-fielder="C"]')).toContainText('홈 포수');await expect(page.locator('.be-flight-trail,.be-throw-trail')).toHaveCount(0);
 if(out)await expect(page.locator('#be-stadium-runners [data-runner-id="1"]')).toHaveCount(0);else await expect(page.locator('#be-stadium-runners [data-runner-id="1"]')).toHaveAttribute('transform',action==='steal'?'translate(360 275)':'translate(525 365)');expect(errors).toEqual([]);await page.evaluate(()=>beCloseGameReplay());
});

test('glove holds the lead without framing distortion or old procedural player shapes',async({page})=>{
 const errors=await open(page,'openFramed');await page.locator('#be-replay-sound').uncheck();await page.locator('#be-replay-next').click();await page.clock.runFor(200);const lead=await page.locator('#be-catcher-mitt').getAttribute('transform');await page.clock.runFor(800);await expect(page.locator('#be-catcher-mitt')).toHaveAttribute('transform',lead);await expect(page.locator('#be-pitch-records')).not.toContainText('프레이밍');await expect(page.locator('.be-pitch-players,.be-batter-stance,#be-batter-swing')).toHaveCount(0);await page.locator('#be-replay-auto').click();await page.locator('.be-stadium').screenshot({path:'test-results/fixed-glove.png'});expect(errors).toEqual([]);await page.evaluate(()=>beCloseGameReplay());
});
test('legacy innings still play with the compact controls',async({page})=>{
 const errors=await open(page,'openLegacy');await expect(page.locator('.be-pitch-record-panel')).toBeHidden();await page.locator('#be-replay-speed').selectOption('3');await page.locator('#be-replay-next').click();await page.clock.runFor(30000);await expect(page.locator('#be-replay-current-score')).toHaveText('0 : 1');await expect(page.locator('#be-replay-next')).toBeDisabled();expect(errors).toEqual([]);await page.evaluate(()=>beCloseGameReplay());
});

test('recorded samples decode, mute stops playback, and result calls avoid duplicate strikeout',async({page})=>{
 const errors=await open(page);await page.evaluate(()=>{window.voiceCalls=[];window.sampleStarts=[];window.decodedCount=0;window.beReplayVoice={prepare:()=>Promise.resolve({available:true}),speak:({text})=>{window.voiceCalls.push(text);return Promise.resolve({spoken:true})},stop:()=>Promise.resolve()};const proto=AudioContext.prototype,decode=proto.decodeAudioData,create=proto.createBufferSource;proto.decodeAudioData=function(bytes){return decode.call(this,bytes).then(buffer=>{window.decodedCount++;return buffer})};proto.createBufferSource=function(){const node=create.call(this),start=node.start;node.start=function(...args){window.sampleStarts.push(node.buffer?.duration);return start.apply(node,args)};return node;};});
 await page.locator('#be-replay-next').click();await page.waitForFunction(()=>window.decodedCount>=18);await page.clock.runFor(2000);await page.locator('#be-replay-auto').click();expect(await page.evaluate(()=>window.sampleStarts.length)).toBeGreaterThan(0);
 await page.locator('#be-replay-sound').uncheck();const before=await page.evaluate(()=>window.sampleStarts.length);await frame(page);expect(await page.evaluate(()=>window.sampleStarts.length)).toBe(before);await page.locator('#be-replay-sound').check();await frame(page);await expect(page.locator('#be-contact-effect circle')).toHaveCount(1);await frame(page);expect(await page.evaluate(()=>window.voiceCalls)).toEqual([]);await frame(page);const afterK=await page.evaluate(()=>window.sampleStarts.length);await frame(page);expect(await page.evaluate(()=>window.sampleStarts.length)).toBe(afterK);await frame(page);await frame(page);expect(await page.evaluate(()=>window.voiceCalls)).toEqual([]);await expect(page.locator('.be-stadium')).toHaveAttribute('data-celebration','homer');expect(errors).toEqual([]);await page.evaluate(()=>beCloseGameReplay());
});
